    (297, 'Challenger Model', 'Total Verizon - Below the line (BTL)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Total Verizon - Total Interest Expense] + [Total Verizon - Equity (Income) Loss from Unconsolidated Business] + [Total Verizon - Other Income and Expense] + [Total Verizon - Noncontrolling Interest]', TRUE, NULL)
  ])
),
Config AS (
  SELECT
    Config_ID,
    TRIM(LineItem) AS LineItem,
    IF((ProfitCentre IS NULL OR TRIM(ProfitCentre) = '' OR UPPER(TRIM(ProfitCentre)) IN ('ALL', 'NA')), 'ALL', TRIM(ProfitCentre)) AS ProfitCentre,
    NULLIF(TRIM(ProfitCentreHierarchyName), '') AS ProfitCentreHierarchyName,
    IF((Account IS NULL OR TRIM(Account) = '' OR UPPER(TRIM(Account)) IN ('ALL', 'NA')), 'ALL', TRIM(Account)) AS Account,
    NULLIF(TRIM(AccountHierarchy), '') AS AccountHierarchy,
    IF((CompanyCode IS NULL OR TRIM(CompanyCode) = '' OR UPPER(TRIM(CompanyCode)) IN ('ALL', 'NA')), 'ALL', TRIM(CompanyCode)) AS CompanyCode,
    IF((CostCenter IS NULL OR TRIM(CostCenter) = '' OR UPPER(TRIM(CostCenter)) IN ('ALL', 'NA')), 'ALL', TRIM(CostCenter)) AS CostCenter,
    IF((Market IS NULL OR TRIM(Market) = '' OR UPPER(TRIM(Market)) IN ('ALL', 'NA')), 'ALL', TRIM(Market)) AS Market,
    IF((DistributionChannel IS NULL OR TRIM(DistributionChannel) = '' OR UPPER(TRIM(DistributionChannel)) IN ('ALL', 'NA')), 'ALL', TRIM(DistributionChannel)) AS DistributionChannel,
    NULLIF(TRIM(DistributionChannelHierarchy), '') AS DistributionChannelHierarchy
  FROM config_csv
  WHERE (Formula IS NULL OR TRIM(Formula) = '')
),
profitcentre_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ProfitCentre) AS ProfitCentreGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ProfitCentre = H.parent
    AND H.dimension_name = 'Profit_Center'
    AND (CASE WHEN C.ProfitCentreHierarchyName IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProfitCentreHierarchyName END)
  WHERE C.ProfitCentre <> 'ALL'
),
account_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Account) AS AccountGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Account = H.parent
    AND H.dimension_name = 'Account'
    AND (CASE WHEN C.AccountHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.AccountHierarchy END)
  WHERE C.Account <> 'ALL'
),
companycode_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.CompanyCode) AS CompanyCodeGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.CompanyCode = H.parent
    AND H.dimension_name = 'Company_Code'
    AND (H.is_primary = TRUE)
  WHERE C.CompanyCode <> 'ALL'
),
costcenter_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.CostCenter) AS CostCenterGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.CostCenter = H.parent
    AND H.dimension_name = 'Cost_Center'
    AND (H.is_primary = TRUE)
  WHERE C.CostCenter <> 'ALL'
),
market_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Market) AS MarketGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Market = H.parent
    AND H.dimension_name = 'Market'
    AND (H.is_primary = TRUE)
  WHERE C.Market <> 'ALL'
),
distributionchannel_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.DistributionChannel) AS DistributionChannelGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.DistributionChannel = H.parent
    AND H.dimension_name = 'Distribution_Channel'
    AND (CASE WHEN C.DistributionChannelHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.DistributionChannelHierarchy END)
  WHERE C.DistributionChannel <> 'ALL'
),
actuals AS (
  SELECT T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Cost_Center, T.Market, T.Distribution_Channel, SUM(CAST(T.amount AS NUMERIC)) AS amount
  FROM `vz-it-np-j0nv-dev-oddo-0.od_published_epm.epm_p00exp_plan_bdgt_v` T
  INNER JOIN (SELECT DISTINCT ProfitCentreGranular FROM profitcentre_mapping) F_ProfitCentre
    ON F_ProfitCentre.ProfitCentreGranular = T.profit_center
  INNER JOIN (SELECT DISTINCT AccountGranular FROM account_mapping) F_Account
    ON F_Account.AccountGranular = T.Account
  INNER JOIN (SELECT DISTINCT CompanyCodeGranular FROM companycode_mapping) F_CompanyCode
    ON F_CompanyCode.CompanyCodeGranular = T.Company_Code
  INNER JOIN (SELECT DISTINCT CostCenterGranular FROM costcenter_mapping) F_CostCenter
    ON F_CostCenter.CostCenterGranular = T.Cost_Center
  INNER JOIN (SELECT DISTINCT MarketGranular FROM market_mapping) F_Market
    ON F_Market.MarketGranular = T.Market
  INNER JOIN (SELECT DISTINCT DistributionChannelGranular FROM distributionchannel_mapping) F_DistributionChannel
    ON F_DistributionChannel.DistributionChannelGranular = T.Distribution_Channel
  WHERE T.scenario = 'SC.CV'
    AND T.version = 'VR.SUB.8'
    AND T.year IN (
      SELECT FORMAT_DATE('FY%y', DATE_SUB(DATE_ADD(CURRENT_DATE(), INTERVAL 0 MONTH), INTERVAL i YEAR))
      FROM UNNEST(GENERATE_ARRAY(0, 4)) AS i)
    AND CAST(T.period AS STRING) NOT IN ('BegBalance')
  GROUP BY T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Cost_Center, T.Market, T.Distribution_Channel
),
base_values AS (
  SELECT C.LineItem, A.year AS year, A.period AS month, SUM(A.amount) AS Amount
  FROM actuals A
  INNER JOIN profitcentre_mapping M_ProfitCentre
    ON M_ProfitCentre.ProfitCentreGranular = A.profit_center
  INNER JOIN Config C
    ON C.Config_ID = M_ProfitCentre.Config_ID
  INNER JOIN account_mapping M_Account
    ON M_Account.Config_ID = C.Config_ID
    AND M_Account.AccountGranular = A.Account
  INNER JOIN companycode_mapping M_CompanyCode
    ON M_CompanyCode.Config_ID = C.Config_ID
    AND M_CompanyCode.CompanyCodeGranular = A.Company_Code
  INNER JOIN costcenter_mapping M_CostCenter
    ON M_CostCenter.Config_ID = C.Config_ID
    AND M_CostCenter.CostCenterGranular = A.Cost_Center
  INNER JOIN market_mapping M_Market
    ON M_Market.Config_ID = C.Config_ID
    AND M_Market.MarketGranular = A.Market
  INNER JOIN distributionchannel_mapping M_DistributionChannel
    ON M_DistributionChannel.Config_ID = C.Config_ID
    AND M_DistributionChannel.DistributionChannelGranular = A.Distribution_Channel
  GROUP BY C.LineItem, A.year, A.period
)
SELECT LineItem, year, month, Amount
FROM base_values;

WITH
monthly_summary AS (
  SELECT year, month, LineItem, CAST(COALESCE(SUM(Amount), 0) AS NUMERIC) AS Amount
  FROM `base_values`
  GROUP BY year, month, LineItem
),

monthly_summary_dated AS (
  -- month_date orders the months for LAG / rolling / roll-forward; a year or month it cannot read stops the query
  SELECT
    year, month, LineItem, Amount,
    IF(month_date IS NULL,
       ERROR(FORMAT('cannot turn year %T / month %T into a date (fix the month mapping or add the period to EXCLUDED_PERIODS)', year, month)),
       month_date) AS month_date
  FROM (
    SELECT *, SAFE.DATE(IF(year_num < 100, 2000 + year_num, year_num), month_num, 1) AS month_date
    FROM (
      SELECT
        *,
        SAFE_CAST(REGEXP_REPLACE(CAST(year AS STRING), r'^[Ff][Yy]', '') AS INT64) AS year_num,
        CASE LOWER(TRIM(CAST(month AS STRING)))
          WHEN 'jan' THEN 1 WHEN 'january' THEN 1
          WHEN 'feb' THEN 2 WHEN 'february' THEN 2
          WHEN 'mar' THEN 3 WHEN 'march' THEN 3
          WHEN 'apr' THEN 4 WHEN 'april' THEN 4
          WHEN 'may' THEN 5
          WHEN 'jun' THEN 6 WHEN 'june' THEN 6
          WHEN 'jul' THEN 7 WHEN 'july' THEN 7
          WHEN 'aug' THEN 8 WHEN 'august' THEN 8
          WHEN 'sep' THEN 9 WHEN 'september' THEN 9
          WHEN 'oct' THEN 10 WHEN 'october' THEN 10
          WHEN 'nov' THEN 11 WHEN 'november' THEN 11
          WHEN 'dec' THEN 12 WHEN 'december' THEN 12
          ELSE SAFE_CAST(TRIM(CAST(month AS STRING)) AS INT64)
        END AS month_num
      FROM monthly_summary
    )
  )
),

combined_0 AS (
  SELECT year, month, month_date, LineItem, Amount FROM monthly_summary_dated
),

tier_1_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer - Devices non-WLS = [Calculated Consumer - Devices WLS] - [Consumer - Devices WLS]  (Config_ID 264)
    SUM(IF(LineItem = 'Calculated Consumer - Devices WLS', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Devices WLS', Amount, 0)) AS f_264,
    -- Consumer - Transportation and Logistics Direct Costs non-WLS = [Calculated Consumer - Transportation and Logistics Direct Costs WLS] - [Consumer - Transportation and Logistics Direct Costs WLS]  (Config_ID 265)
    SUM(IF(LineItem = 'Calculated Consumer - Transportation and Logistics Direct Costs WLS', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Transportation and Logistics Direct Costs WLS', Amount, 0)) AS f_265,
    -- Business - Devices non-WLS = [Calculated Business - Devices WLS] - [Business - Devices WLS]  (Config_ID 266)
    SUM(IF(LineItem = 'Calculated Business - Devices WLS', Amount, 0)) - SUM(IF(LineItem = 'Business - Devices WLS', Amount, 0)) AS f_266,
    -- Business - Transportation and Logistics Direct Costs non-WLS = [Calculated Business - Transportation and Logistics Direct Costs WLS] - [Business - Transportation and Logistics Direct Costs WLS]  (Config_ID 267)
    SUM(IF(LineItem = 'Calculated Business - Transportation and Logistics Direct Costs WLS', Amount, 0)) - SUM(IF(LineItem = 'Business - Transportation and Logistics Direct Costs WLS', Amount, 0)) AS f_267,
    -- Org Other - Devices = [Calculated Org Other - Devices1] + [Calculated Org Other - Devices2] + [Calculated Org Other - Devices3]  (Config_ID 268)
    SUM(IF(LineItem = 'Calculated Org Other - Devices1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Devices2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Devices3', Amount, 0)) AS f_268,
    -- Org Other - Transportation and Logistics Direct Costs = [Calculated Org Other - Transportation and Logistics Direct Costs1] + [Calculated Org Other - Transportation and Logistics Direct Costs2] + [Calculated Org Other - Transportation and Logistics Direct Costs3]  (Config_ID 269)
    SUM(IF(LineItem = 'Calculated Org Other - Transportation and Logistics Direct Costs1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Transportation and Logistics Direct Costs2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Transportation and Logistics Direct Costs3', Amount, 0)) AS f_269,
    -- Org Other - Digital Content = [Calculated Org Other - Digital Content1] + [Calculated Org Other - Digital Content2] + [Calculated Org Other - Digital Content3]  (Config_ID 270)
    SUM(IF(LineItem = 'Calculated Org Other - Digital Content1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Digital Content2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Digital Content3', Amount, 0)) AS f_270,
    -- Org Other - Products and Services = [Calculated Org Other - Products and Services1] + [Calculated Org Other - Products and Services2] + [Calculated Org Other - Products and Services3]  (Config_ID 271)
    SUM(IF(LineItem = 'Calculated Org Other - Products and Services1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Products and Services2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Products and Services3', Amount, 0)) AS f_271,
    -- Org Other - Roaming = [Calculated Org Other - Roaming1] + [Calculated Org Other - Roaming2] + [Calculated Org Other - Roaming3]  (Config_ID 272)
    SUM(IF(LineItem = 'Calculated Org Other - Roaming1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Roaming2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Roaming3', Amount, 0)) AS f_272,
    -- Org Other - Customer Access Costs = [Calculated Org Other - Customer Access Costs1] + [Calculated Org Other - Customer Access Costs2] + [Calculated Org Other - Customer Access Costs3]  (Config_ID 273)
    SUM(IF(LineItem = 'Calculated Org Other - Customer Access Costs1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Customer Access Costs2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Customer Access Costs3', Amount, 0)) AS f_273,
    -- Org Other - Network Access Costs = [Calculated Org Other - Network Access Costs1] + [Calculated Org Other - Network Access Costs2] + [Calculated Org Other - Network Access Costs3]  (Config_ID 274)
    SUM(IF(LineItem = 'Calculated Org Other - Network Access Costs1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Network Access Costs2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Network Access Costs3', Amount, 0)) AS f_274,
    -- Org Other - Bad Debt Expense = [Calculated Org Other - Bad Debt Expense1] + [Calculated Org Other - Bad Debt Expense2] + [Calculated Org Other - Bad Debt Expense3]  (Config_ID 275)
    SUM(IF(LineItem = 'Calculated Org Other - Bad Debt Expense1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Bad Debt Expense2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Bad Debt Expense3', Amount, 0)) AS f_275,
    -- Org Other - Advertising and Promotion = [Calculated Org Other - Advertising and Promotion1] + [Calculated Org Other - Advertising and Promotion2] + [Calculated Org Other - Advertising and Promotion3]  (Config_ID 276)
    SUM(IF(LineItem = 'Calculated Org Other - Advertising and Promotion1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Advertising and Promotion2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Advertising and Promotion3', Amount, 0)) AS f_276,
    -- Org Other - Full Time Labor = [Calculated Org Other - Full Time Labor1] + [Calculated Org Other - Full Time Labor2] + [Calculated Org Other - Full Time Labor3]  (Config_ID 277)
    SUM(IF(LineItem = 'Calculated Org Other - Full Time Labor1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Full Time Labor2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Full Time Labor3', Amount, 0)) AS f_277,
    -- Org Other - Travel and Internal Events = [Calculated Org Other - Travel and Internal Events1] + [Calculated Org Other - Travel and Internal Events2] + [Calculated Org Other - Travel and Internal Events3]  (Config_ID 278)
    SUM(IF(LineItem = 'Calculated Org Other - Travel and Internal Events1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Travel and Internal Events2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Travel and Internal Events3', Amount, 0)) AS f_278,
    -- Org Other - HR and Training = [Calculated Org Other - HR and Training1] + [Calculated Org Other - HR and Training2] + [Calculated Org Other - HR and Training3]  (Config_ID 279)
    SUM(IF(LineItem = 'Calculated Org Other - HR and Training1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - HR and Training2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - HR and Training3', Amount, 0)) AS f_279,
    -- Org Other - Outsourced Functions = [Calculated Org Other - Outsourced Functions1] + [Calculated Org Other - Outsourced Functions2] + [Calculated Org Other - Outsourced Functions3]  (Config_ID 280)
    SUM(IF(LineItem = 'Calculated Org Other - Outsourced Functions1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Outsourced Functions2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Outsourced Functions3', Amount, 0)) AS f_280,
    -- Org Other - Professional Services Fees = [Calculated Org Other - Professional Services Fees1] + [Calculated Org Other - Professional Services Fees2] + [Calculated Org Other - Professional Services Fees3]  (Config_ID 281)
    SUM(IF(LineItem = 'Calculated Org Other - Professional Services Fees1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Professional Services Fees2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Professional Services Fees3', Amount, 0)) AS f_281,
    -- Org Other - Contracted and Temporary Labor = [Calculated Org Other - Contracted and Temporary Labor1] + [Calculated Org Other - Contracted and Temporary Labor2] + [Calculated Org Other - Contracted and Temporary Labor3]  (Config_ID 282)
    SUM(IF(LineItem = 'Calculated Org Other - Contracted and Temporary Labor1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Contracted and Temporary Labor2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Contracted and Temporary Labor3', Amount, 0)) AS f_282,
    -- Org Other - Sales Incentives = [Calculated Org Other - Sales Incentives1] + [Calculated Org Other - Sales Incentives2] + [Calculated Org Other - Sales Incentives3]  (Config_ID 283)
    SUM(IF(LineItem = 'Calculated Org Other - Sales Incentives1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Sales Incentives2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Sales Incentives3', Amount, 0)) AS f_283,
    -- Org Other - IT and Technology Contracts = [Calculated Org Other - IT and Technology Contracts1] + [Calculated Org Other - IT and Technology Contracts2] + [Calculated Org Other - IT and Technology Contracts3]  (Config_ID 284)
    SUM(IF(LineItem = 'Calculated Org Other - IT and Technology Contracts1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - IT and Technology Contracts2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - IT and Technology Contracts3', Amount, 0)) AS f_284,
    -- Org Other - Building and Facilities = [Calculated Org Other - Building and Facilities1] + [Calculated Org Other - Building and Facilities2] + [Calculated Org Other - Building and Facilities3]  (Config_ID 285)
    SUM(IF(LineItem = 'Calculated Org Other - Building and Facilities1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Building and Facilities2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Building and Facilities3', Amount, 0)) AS f_285,
    -- Org Other - Transportation and Logistics Operating Costs = [Calculated Org Other - Transportation and Logistics Operating Costs1] + [Calculated Org Other - Transportation and Logistics Operating Costs2] + [Calculated Org Other - Transportation and Logistics Operating Costs3]  (Config_ID 286)
    SUM(IF(LineItem = 'Calculated Org Other - Transportation and Logistics Operating Costs1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Transportation and Logistics Operating Costs2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Transportation and Logistics Operating Costs3', Amount, 0)) AS f_286,
    -- Org Other - Network Equipment and Maintenance = [Calculated Org Other - Network Equipment and Maintenance1] + [Calculated Org Other - Network Equipment and Maintenance2] + [Calculated Org Other - Network Equipment and Maintenance3]  (Config_ID 287)
    SUM(IF(LineItem = 'Calculated Org Other - Network Equipment and Maintenance1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Network Equipment and Maintenance2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Network Equipment and Maintenance3', Amount, 0)) AS f_287,
    -- Org Other - Rent and Lease Expense = [Calculated Org Other - Rent and Lease Expense1] + [Calculated Org Other - Rent and Lease Expense2] + [Calculated Org Other - Rent and Lease Expense3]  (Config_ID 288)
    SUM(IF(LineItem = 'Calculated Org Other - Rent and Lease Expense1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Rent and Lease Expense2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Rent and Lease Expense3', Amount, 0)) AS f_288,
    -- Org Other - Gain/Loss on Sale of Assets = [Calculated Org Other - Gain/Loss on Sale of Assets1] + [Calculated Org Other - Gain/Loss on Sale of Assets2] + [Calculated Org Other - Gain/Loss on Sale of Assets3]  (Config_ID 289)
    SUM(IF(LineItem = 'Calculated Org Other - Gain/Loss on Sale of Assets1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Gain/Loss on Sale of Assets2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Gain/Loss on Sale of Assets3', Amount, 0)) AS f_289,
    -- Org Other - Other Admin Costs = [Calculated Org Other - Other Admin Costs1] + [Calculated Org Other - Other Admin Costs2] + [Calculated Org Other - Other Admin Costs3]  (Config_ID 290)
    SUM(IF(LineItem = 'Calculated Org Other - Other Admin Costs1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Other Admin Costs2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Other Admin Costs3', Amount, 0)) AS f_290,
    -- Org Other - Financial Transaction Charges = [Calculated Org Other - Financial Transaction Charges1] + [Calculated Org Other - Financial Transaction Charges2] + [Calculated Org Other - Financial Transaction Charges3]  (Config_ID 291)
    SUM(IF(LineItem = 'Calculated Org Other - Financial Transaction Charges1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Financial Transaction Charges2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Financial Transaction Charges3', Amount, 0)) AS f_291,
    -- Org Other - Regulatory and Compliance = [Calculated Org Other - Regulatory and Compliance1] + [Calculated Org Other - Regulatory and Compliance2] + [Calculated Org Other - Regulatory and Compliance3]  (Config_ID 292)
    SUM(IF(LineItem = 'Calculated Org Other - Regulatory and Compliance1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Regulatory and Compliance2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Regulatory and Compliance3', Amount, 0)) AS f_292,
    -- Org Other - Affiliate Billing = [Calculated Org Other - Affiliate Billing1] + [Calculated Org Other - Affiliate Billing2] + [Calculated Org Other - Affiliate Billing3]  (Config_ID 293)
    SUM(IF(LineItem = 'Calculated Org Other - Affiliate Billing1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Affiliate Billing2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Affiliate Billing3', Amount, 0)) AS f_293,
    -- Org Other - Insurance Costs = [Calculated Org Other - Insurance Costs1] + [Calculated Org Other - Insurance Costs2] + [Calculated Org Other - Insurance Costs3]  (Config_ID 294)
    SUM(IF(LineItem = 'Calculated Org Other - Insurance Costs1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Insurance Costs2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Insurance Costs3', Amount, 0)) AS f_294,
    -- Org Other - Taxes and Penalties = [Calculated Org Other - Taxes and Penalties1] + [Calculated Org Other - Taxes and Penalties2] + [Calculated Org Other - Taxes and Penalties3]  (Config_ID 295)
    SUM(IF(LineItem = 'Calculated Org Other - Taxes and Penalties1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Taxes and Penalties2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Taxes and Penalties3', Amount, 0)) AS f_295,
    -- Total Verizon - Total Interest Expense = [Total Verizon - Gross Interest Expense] + [Total Verizon - Interest During Construction]  (Config_ID 296)
    SUM(IF(LineItem = 'Total Verizon - Gross Interest Expense', Amount, 0)) + SUM(IF(LineItem = 'Total Verizon - Interest During Construction', Amount, 0)) AS f_296
  FROM combined_0
  GROUP BY year, month, month_date
),

tier_1 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_1_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount NUMERIC>>[
    ('Consumer - Devices non-WLS', calc.f_264),
    ('Consumer - Transportation and Logistics Direct Costs non-WLS', calc.f_265),
    ('Business - Devices non-WLS', calc.f_266),
    ('Business - Transportation and Logistics Direct Costs non-WLS', calc.f_267),
    ('Org Other - Devices', calc.f_268),
    ('Org Other - Transportation and Logistics Direct Costs', calc.f_269),
    ('Org Other - Digital Content', calc.f_270),
    ('Org Other - Products and Services', calc.f_271),
    ('Org Other - Roaming', calc.f_272),
    ('Org Other - Customer Access Costs', calc.f_273),
    ('Org Other - Network Access Costs', calc.f_274),
    ('Org Other - Bad Debt Expense', calc.f_275),
    ('Org Other - Advertising and Promotion', calc.f_276),
    ('Org Other - Full Time Labor', calc.f_277),
    ('Org Other - Travel and Internal Events', calc.f_278),
    ('Org Other - HR and Training', calc.f_279),
    ('Org Other - Outsourced Functions', calc.f_280),
    ('Org Other - Professional Services Fees', calc.f_281),
    ('Org Other - Contracted and Temporary Labor', calc.f_282),
    ('Org Other - Sales Incentives', calc.f_283),
    ('Org Other - IT and Technology Contracts', calc.f_284),
    ('Org Other - Building and Facilities', calc.f_285),
    ('Org Other - Transportation and Logistics Operating Costs', calc.f_286),
    ('Org Other - Network Equipment and Maintenance', calc.f_287),
    ('Org Other - Rent and Lease Expense', calc.f_288),
    ('Org Other - Gain/Loss on Sale of Assets', calc.f_289),
    ('Org Other - Other Admin Costs', calc.f_290),
    ('Org Other - Financial Transaction Charges', calc.f_291),
    ('Org Other - Regulatory and Compliance', calc.f_292),
    ('Org Other - Affiliate Billing', calc.f_293),
    ('Org Other - Insurance Costs', calc.f_294),
    ('Org Other - Taxes and Penalties', calc.f_295),
    ('Total Verizon - Total Interest Expense', calc.f_296)
  ]) AS item
),

tier_1_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Consumer - Devices non-WLS',
    'Consumer - Transportation and Logistics Direct Costs non-WLS',
    'Business - Devices non-WLS',
    'Business - Transportation and Logistics Direct Costs non-WLS',
    'Org Other - Devices',
    'Org Other - Transportation and Logistics Direct Costs',
    'Org Other - Digital Content',
    'Org Other - Products and Services',
    'Org Other - Roaming',
    'Org Other - Customer Access Costs',
    'Org Other - Network Access Costs',
    'Org Other - Bad Debt Expense',
    'Org Other - Advertising and Promotion',
    'Org Other - Full Time Labor',
    'Org Other - Travel and Internal Events',
    'Org Other - HR and Training',
    'Org Other - Outsourced Functions',
    'Org Other - Professional Services Fees',
    'Org Other - Contracted and Temporary Labor',
    'Org Other - Sales Incentives',
    'Org Other - IT and Technology Contracts',
    'Org Other - Building and Facilities',
    'Org Other - Transportation and Logistics Operating Costs',
    'Org Other - Network Equipment and Maintenance',
    'Org Other - Rent and Lease Expense',
    'Org Other - Gain/Loss on Sale of Assets',
    'Org Other - Other Admin Costs',
    'Org Other - Financial Transaction Charges',
    'Org Other - Regulatory and Compliance',
    'Org Other - Affiliate Billing',
    'Org Other - Insurance Costs',
    'Org Other - Taxes and Penalties',
    'Total Verizon - Total Interest Expense'
  ]) AS LineItem
),

combined_1 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_0 AS c
  LEFT JOIN tier_1_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_1
),

tier_2_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Total Verizon - Below the line (BTL) = [Total Verizon - Total Interest Expense] + [Total Verizon - Equity (Income) Loss from Unconsolidated Business] + [Total Verizon - Other Income and Expense] + [Total Verizon - Noncontrolling Interest]  (Config_ID 297)
    SUM(IF(LineItem = 'Total Verizon - Total Interest Expense', Amount, 0)) + SUM(IF(LineItem = 'Total Verizon - Equity (Income) Loss from Unconsolidated Business', Amount, 0)) + SUM(IF(LineItem = 'Total Verizon - Other Income and Expense', Amount, 0)) + SUM(IF(LineItem = 'Total Verizon - Noncontrolling Interest', Amount, 0)) AS f_297
  FROM combined_1
  GROUP BY year, month, month_date
),

tier_2 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_2_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount NUMERIC>>[
    ('Total Verizon - Below the line (BTL)', calc.f_297)
  ]) AS item
),

tier_2_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Total Verizon - Below the line (BTL)'
  ]) AS LineItem
),

combined_2 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_1 AS c
  LEFT JOIN tier_2_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_2
),

